referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const object = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
  const out = clone(d.value);
  let n = out;
  for (const k of d.path.slice(0, -1)) n = n[k];
  const k = d.path.at(-1),
    old = n[k],
    v = d.replacement;
  n[k] =
    Array.isArray(old) && Array.isArray(v)
      ? old.concat(clone(v))
      : object(old) && object(v)
        ? { ...old, ...clone(v) }
        : clone(v);
  return out;
}

